    "text": "ええ。前もって種を水につけてから撒かないとだめなものとかもありますしね。あと、苗から育てたことがあるなら、土の準備とかはご存知でしょうかね。最初に土に肥料を入れて、しばらく寝かせる必要があるんですけど。",
