    "text": "僕も国の文献、手に入れるの大変でした。僕は建築が専門なんで、日本と自分の国の住宅の歴史的変遷をテーマにして書いてるんですけど、指定の枚数を超えてしまって、短くしないといけないんですけど、なかなか。",
